action.command:
cd /workspace && cat > /tmp/validate-profile.mjs <<'EOF'
import { buildProfileEnv } from '/workspace/scripts/ops/runtime/profile-env.ts';
import { assertRuntimeEnv } from '/workspace/scripts/ops/runtime/profile-env.ts';

const env = buildProfileEnv('local-builder', { rootDir: '/workspace' });
try {
  assertRuntimeEnv('local-builder', env);
  console.log('VALIDATION OK');
} catch (e) {
  console.log('VALIDATION FAILED:\n' + e.message);
}
EOF
timeout 120 pnpm exec tsx /tmp/validate-profile.mjs 2>&1 | tail -20

